initJs:
function(container, apiUrl, tables) {
  const tbody = container.querySelector("#history-tbody");
  const modal = container.querySelector("#detail-modal");

  let currentPage = 1;
  const itemsPerPage = 20;
  let allRows = [];
  let filteredRows = [];
  let users = [];

  // ユーザー一覧を取得してセレクトボックスに設定
  async function loadUsers() {
    try {
      const userRows = await window.aivicApi.list(0); // ログインユーザーテーブル
      if (userRows) {
        users = userRows;
        const userSelect = container.querySelector("#user-filter");
        userSelect.innerHTML = '<option value="">全ユーザー</option>';
        users.forEach(user => {
          userSelect.innerHTML += `<option value="${user.ユーザーID}">${user.ユーザー名}</option>`;
        });
      }
    } catch (error) {
      console.error('ユーザー一覧の取得に失敗しました:', error);
    }
  }

  // 操作履歴テーブル再描画関数
  function renderRows(rows) {
    const startIndex = (currentPage - 1) * itemsPerPage;
    const endIndex = startIndex + itemsPerPage;
    const pageRows = rows.slice(startIndex, endIndex);

    tbody.innerHTML = pageRows.map(r => {
      const user = users.find(u => u.ユーザーID === r.ユーザーID);
      const userName = user ? user.ユーザー名 : 'Unknown';
      const operationDate = r.操作日時 ? new Date(r.操作日時).toLocaleString('ja-JP') : '';
      const resultClass = r.処理結果 === '成功' ? 'status-success' : r.処理結果 === '失敗' || r.処理結果 === 'エラー' ? 'status-error' : '';

      return `<tr data-id="${r.操作履歴ID || ''}">
        <td>${operationDate}</td>
        <td>${userName}</td>
        <td>${r.操作種別 || ''}</td>
        <td>${r.操作画面 || ''}</td>
        <td>${r.IPアドレス || ''}</td>
        <td><span class="${resultClass}">${r.処理結果 || ''}</span></td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${r.操作履歴ID || ''}">詳細</button>
        </td>
      </tr>`;
    }).join("");

    updatePaginationInfo(rows.length, startIndex, endIndex);
    renderPagination(rows.length);
  }

  // ページネーション情報更新
  function updatePaginationInfo(totalItems, startIndex, endIndex) {
    const info = container.querySelector("#pagination-info");
    const actualEnd = Math.min(endIndex, totalItems);
    info.textContent = `${totalItems}件中 ${startIndex + 1}-${actualEnd}件を表示`;
  }

  // ページネーション描画
  function renderPagination(totalItems) {
    const totalPages = Math.ceil(totalItems / itemsPerPage);
    const pageNumbers = container.querySelector("#page-numbers");
    const prevBtn = container.querySelector("#btn-prev");
    const nextBtn = container.querySelector("#btn-next");

    prevBtn.disabled = currentPage === 1;
    nextBtn.disabled = currentPage === totalPages || totalPages === 0;

    pageNumbers.innerHTML = '';

    if (totalPages <= 1) return;

    const startPage = Math.max(1, currentPage - 2);
    const endPage = Math.min(totalPages, currentPage + 2);

    for (let i = startPage; i <= endPage; i++) {
      const btn = document.createElement('button');
      btn.className = `page-btn ${i === currentPage ? 'active' : ''}`;
      btn.textContent = i;
      btn.addEventListener('click', () => {
        currentPage = i;
        renderRows(filteredRows);
      });
      pageNumbers.appendChild(btn);
    }
  }

  // フィルタリング関数
  function applyFilters() {
    const startDate = container.querySelector("#start-date").value;
    const endDate = container.querySelector("#end-date").value;
    const userFilter = container.querySelector("#user-filter").value;
    const operationFilter = container.querySelector("#operation-type-filter").value;
    const screenSearch = container.querySelector("#screen-search").value.toLowerCase();
    const ipSearch = container.querySelector("#ip-search").value.toLowerCase();
    const resultFilter = container.querySelector("#result-filter").value;

    // 日付範囲バリデーション
    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      alert('開始日が終了日より後の日付になっています。正しい日付範囲を入力してください。');
      return;
    }

    filteredRows = allRows.filter(row => {
      // 日付範囲フィルター
      if (startDate || endDate) {
        const rowDate = row.操作日時 ? new Date(row.操作日時).toISOString().split('T')[0] : '';
        if (startDate && rowDate < startDate) return false;
        if (endDate && rowDate > endDate) return false;
      }

      // ユーザーフィルター
      if (userFilter && row.ユーザーID !== userFilter) return false;

      // 操作種別フィルター
      if (operationFilter && row.操作種別 !== operationFilter) return false;

      // 画面名検索
      if (screenSearch && !row.操作画面?.toLowerCase().includes(screenSearch)) return false;

      // IPアドレス検索
      if (ipSearch) {
        // IPアドレス形式バリデーション
        const ipPattern = /^(\d{1,3}\.){3}\d{1,3}$/;
        if (ipSearch && !ipPattern.test(ipSearch) && ipSearch.length > 0) {
          alert('不正なIPアドレス形式です。正しい形式（例：192.168.1.100）で入力してください。');
          return false;
        }
        if (!row.IPアドレス?.toLowerCase().includes(ipSearch)) return false;
      }

      // 処理結果フィルター
      if (resultFilter && row.処理結果 !== resultFilter) return false;

      return true;
    });

    currentPage = 1;
    renderRows(filteredRows);
  }

  // 詳細モーダル表示
  function showDetailModal(historyId) {
    const history = allRows.find(r => r.操作履歴ID === historyId);
    if (!history) return;

    const user = users.find(u => u.ユーザーID === history.ユーザーID);
    const userName = user ? user.ユーザー名 : 'Unknown';

    container.querySelector("#detail-id").textContent = history.操作履歴ID || '';
    container.querySelector("#detail-datetime").textContent = history.操作日時 ? new Date(history.操作日時).toLocaleString('ja-JP') : '';
    container.querySelector("#detail-user").textContent = userName;
    container.querySelector("#detail-operation").textContent = history.操作種別 || '';
    container.querySelector("#detail-screen").textContent = history.操作画面 || '';
    container.querySelector("#detail-table").textContent = history.操作対象テーブル || '';
    container.querySelector("#detail-target-id").textContent = history.操作対象ID || '';
    container.querySelector("#detail-ip").textContent = history.IPアドレス || '';
    container.querySelector("#detail-user-agent").textContent = history.ユーザーエージェント || '';
    container.querySelector("#detail-result").textContent = history.処理結果 || '';
    container.querySelector("#detail-processing-time").textContent = history.処理時間 ? `${history.処理時間}ms` : '';
    container.querySelector("#detail-content").textContent = history.操作内容 || '';
    container.querySelector("#detail-error").textContent = history.エラーメッセージ || '';

    modal.classList.remove('hidden');
  }

  // CSV出力
  function exportCSV() {
    if (filteredRows.length === 0) {
      alert('出力するデータがありません。');
      return;
    }

    // 大量データの場合の警告
    if (filteredRows.length > 100000) {
      alert('データ量が多すぎるため、CSV出力でタイムアウトエラーが発生する可能性があります。検索条件を絞り込んでから再度お試しください。');
      return;
    }

    const headers = ['操作日時', 'ユーザー名', '操作種別', '操作画面', 'IPアドレス', '処理結果', '操作内容', 'エラーメッセージ'];
    const csvContent = [
      headers.join(','),
      ...filteredRows.map(row => {
        const user = users.find(u => u.ユーザーID === row.ユーザーID);
        const userName = user ? user.ユーザー名 : 'Unknown';
        const operationDate = row.操作日時 ? new Date(row.操作日時).toLocaleString('ja-JP') : '';

        return [
          `"${operationDate}"`,
          `"${userName}"`,
          `"${row.操作種別 || ''}"`,
          `"${row.操作画面 || ''}"`,
          `"${row.IPアドレス || ''}"`,
          `"${row.処理結果 || ''}"`,
          `"${(row.操作内容 || '').replace(/"/g, '""')}"`,
          `"${(row.エラーメッセージ || '').replace(/"/g, '""')}"`
        ].join(',');
      })
    ].join('\n');

    const bom = '\uFEFF';
    const blob = new Blob([bom + csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `操作履歴_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期データ読み込み
  async function loadData() {
    try {
      await loadUsers();
      const rows = await window.aivicApi.list(12); // システム操作履歴テーブル
      if (rows) {
        allRows = rows.sort((a, b) => new Date(b.操作日時) - new Date(a.操作日時));
        filteredRows = [...allRows];
        renderRows(filteredRows);
      } else {
        allRows = tables[12]?.records || [];
        filteredRows = [...allRows];
        renderRows(filteredRows);
      }
    } catch (error) {
      console.error('データの読み込みに失敗しました:', error);
      allRows = tables[12]?.records || [];
      filteredRows = [...allRows];
      renderRows(filteredRows);
    }
  }

  // イベントリスナー登録
  container.querySelector("#btn-search").addEventListener("click", applyFilters);

  container.querySelector("#btn-clear").addEventListener("click", () => {
    container.querySelector("#start-date").value = '';
    container.querySelector("#end-date").value = '';
    container.querySelector("#user-filter").value = '';
    container.querySelector("#operation-type-filter").value = '';
    container.querySelector("#screen-search").value = '';
    container.querySelector("#ip-search").value = '';
    container.querySelector("#result-filter").value = '';

    filteredRows = [...allRows];
    currentPage = 1;
    renderRows(filteredRows);
  });

  container.querySelector("#btn-csv-export").addEventListener("click", exportCSV);

  container.querySelector("#btn-prev").addEventListener("click", () => {
    if (currentPage > 1) {
      currentPage--;
      renderRows(filteredRows);
    }
  });

  container.querySelector("#btn-next").addEventListener("click", () => {
    const totalPages = Math.ceil(filteredRows.length / itemsPerPage);
    if (currentPage < totalPages) {
      currentPage++;
      renderRows(filteredRows);
    }
  });

  container.querySelector("#btn-close-modal").addEventListener("click", () => {
    modal.classList.add('hidden');
  });

  modal.addEventListener("click", (e) => {
    if (e.target === modal) {
      modal.classList.add('hidden');
    }
  });

  // イベントデリゲーション
  container.addEventListener("click", (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      showDetailModal(detailBtn.dataset.id);
    }
  });

  // 初期データ読み込み
  loadData();
}
